=Summarize this email in one concise sentence of no more than 20 words.
Return only a valid JSON object with these keys:
fetchedAt, sender, subject, preview, receivedDate, summary.

Use the provided values exactly for fetchedAt, sender, subject,
preview, and receivedDate. Do not invent missing information.
For summary, describe the email in no more than 20 words.
Do not include Markdown fences or any text outside the JSON object.

Fetched at: {{ $now }}
From: {{ $json.From }}
Subject: {{ $json.Subject }}
Preview: {{ $json.snippet }}
Received date (Gmail internalDate): {{ $json.internalDate }}

parameters.jsCode:
const items = $input.all();

// Clean text and escape HTML before inserting values into the email.
const clean = (value) => String(value ?? '').replace(/\s+/g, ' ').trim();

const escapeHtml = (value) => clean(value).replace(/[&<>"']/g, (char) => ({
  '&': '&amp;',
  '<': '&lt;',
  '>': '&gt;',
  '"': '&quot;',
  "'": '&#39;'
})[char]);

// Parse the JSON text returned by the AI Agent.
const emails = items.map((item) => {
  let data = item.json.output;

  if (typeof data === 'string') {
    data = data.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
    try {
      data = JSON.parse(data);
    } catch (error) {
      throw new Error(`Could not parse AI output: ${error.message}`);
    }
  }

  // Handle either parsed objects or already structured output.
  if (!data || typeof data !== 'object') {
    throw new Error('AI output is not a valid JSON object.');
  }

  // Format Gmail's millisecond timestamp as a readable date.
  const rawDate = data.receivedDate;
  const timestamp = Number(rawDate);
  let receivedDate = clean(rawDate);

  if (Number.isFinite(timestamp) && timestamp > 0) {
    receivedDate = new Intl.DateTimeFormat('en-IN', {
      timeZone: 'Asia/Kolkata',
      day: '2-digit',
      month: 'short',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      hour12: true
    }).format(new Date(timestamp));
  }

  return {
    fetchedAt: clean(data.fetchedAt),
    receivedDate,
    sender: clean(data.sender),
    subject: clean(data.subject),
    summary: clean(data.summary || data.preview || 'No summary')
  };
});

// Build one HTML row per email.
const rows = emails.map((email) => `
  <tr>
    <td>${escapeHtml(email.receivedDate || 'Unknown')}</td>
    <td>${escapeHtml(email.sender || 'Unknown')}</td>
    <td>${escapeHtml(email.subject || '(No subject)')}</td>
    <td>${escapeHtml(email.summary)}</td>
  </tr>
`).join('');

// Construct a single HTML email containing all summaries.
const fetchedAt = emails[0]?.fetchedAt || 'Not available';

const emailBody = `
  <h2>Your ${emails.length} Unread Email Summaries</h2>
  <p>Fetched at: ${escapeHtml(fetchedAt)}</p>
  <table border="1" cellpadding="8" cellspacing="0"
         style="border-collapse:collapse;font-family:Arial,sans-serif;">
    <thead>
      <tr>
        <th>Received Date</th>
        <th>Sender</th>
        <th>Subject</th>
        <th>Summary</th>
      </tr>
    </thead>
    <tbody>${rows}</tbody>
  </table>
`;

// Return exactly one item so Gmail sends one consolidated email.
return [{
  json: {
    emailCount: emails.length,
    subject: `Your ${emails.length} Unread Emails`,
    emailBody
  }
}];
